contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // receive to accept Ether for forwarding to C if tests send here
    receive() external payable {}

    // Drive the contract: fund C, then attempt withdrawAll by caller 'caller' and check balance unchanged unless caller is owner.
    // Parameters:
    // ownerCandidate: an address that may or may not be the owner of c (we don't know externally),
    // recipient: where withdrawAll would send funds,
    // fundAmount: amount of wei to fund c with,
    // callerIsOwner: boolean indicating whether this function call should be made from the owner address (simulated by requiring sender equality).

    // Because we cannot change msg.sender in Solidity, we encode the check by observing behavior when the current msg.sender is equal to c.owner() vs not.
    // The function must be called by an external actor; here we implement the test logic assuming the test runner will call it.

    function runTest(address recipient, uint256 fundAmount) public payable {
        // require enough balance in this contract to forward to c
        require(address(this).balance >= fundAmount, "insufficient test contract balance");

        // Record initial balance of C
        uint256 before = address(c).balance;

        // Fund C with fundAmount
        (bool ok,) = address(c).call{value: fundAmount}(" ");
        require(ok, "funding failed");

        // Ensure it was funded
        uint256 afterFund = address(c).balance;
        require(afterFund == before + fundAmount, "funding not reflected");

        // Try to withdraw all to recipient by calling withdrawAll as the current msg.sender (the caller of runTest)
        // This is the deciding call: on original contract C only the owner can succeed in moving balance out.
        c.withdrawAll(recipient);

        // Observe final balance
        uint256 finalBal = address(c).balance;

        // The distinguishing general rule: if msg.sender is NOT the recorded owner, the balance must remain unchanged.
        // We express that as: either msg.sender == owner OR finalBal == afterFund
        address owner = c.owner();
        assert(msg.sender == owner || finalBal == afterFund);
    }
}

