contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: an arbitrary caller address (potential attacker) and an arbitrary deposit amount
    function testFuzz_property(address caller, uint256 deposit) public {
        // keep deposit in a reasonable wide range but non-zero to exercise transfer
        deposit = bound(deposit, 1, 1 ether);
        // ensure caller is not zero and not the owner (address(this) is the owner)
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // fund this test contract (owner) so C can receive balance
        vm.deal(address(this), deposit);
        // deposit funds into c from owner so contract has balance
        // calling fallback via sending ether
        (bool sent,) = address(c).call{value: deposit}("");
        require(sent, "deposit failed");

        // record balance before
        uint256 before = address(c).balance;
        // sanity: should have the deposit
        require(before == deposit);

        // Now have a non-owner caller attempt to withdraw to themselves
        vm.deal(caller, 0); // ensure caller has some EOA state but no native funds needed
        vm.prank(caller);

        bool ok;
        try c.withdrawAll(payable(caller)) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For the correct contract, only the owner can withdraw,
        // so any non-owner caller's attempt to withdraw should fail (call should revert) and the
        // contract balance should remain unchanged. The mutant that removed the owner check will
        // allow the non-owner call to succeed for some inputs, making ok == true and changing balance.
        // We assert that the call did NOT succeed (ok == false) OR that if it did succeed, the caller
        // must be the owner (which we ensured is not the case). Thus for our setup (caller != owner)
        // the reference must have ok == false; the mutant will produce ok == true for some inputs.
        assertTrue(ok == false);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: deposit some ETH into this test, then forward it to c via fallback, then attempt withdrawAll
    // Parameters:
    // - depositorAmount: amount of wei this test must already hold to fund c
    // - recipient: address to receive withdrawn funds
    // - caller: address that will call c.withdrawAll (must be either the owner or a non-owner depending on verification)

    receive() external payable {}

    function run(uint256 depositorAmount, address payable recipient, address caller) public payable {
        // Preconditions for the test environment
        require(msg.value == depositorAmount, "must send depositorAmount");

        // Send the deposit into c so it holds balance (use fallback payable)
        // Need to ensure this contract has the funds: we just received msg.value equal to depositorAmount
        require(address(this).balance >= depositorAmount);
        (bool ok,) = address(c).call{value: depositorAmount}("");
        require(ok, "deposit to c failed");

        // Record balances observable from public surface
        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBefore = recipient.balance;

        // Call withdrawAll from the specified caller. We cannot change msg.sender in Solidity directly,
        // but the verification environment will model different callers; here we perform the call via low-level
        // call from this contract and require that the EOA caller matches 'caller' by using tx.origin check
        // However using tx.origin is not allowed by constraints; instead, we rely on the verifier to run this function
        // with this contract's address as the caller. To allow the verifier to model both cases, we forward the call
        // via a low-level call that sets msg.sender to this contract. To expose the owner-vs-non-owner distinction
        // through observable effect, we perform two calls: one that attempts withdrawAll and capture whether it reverted.

        // Prepare calldata for withdrawAll(address)
        bytes memory data = abi.encodeWithSignature("withdrawAll(address)", recipient);
        (bool success, ) = address(c).call(data);

        // After the call, observe balances
        uint256 cBalanceAfter = address(c).balance;
        uint256 recipientAfter = recipient.balance;

        // The distinguishing rule: If the caller is equal to the public owner getter of c, then the call must succeed
        // and transfer the entire c balance to recipient; otherwise the call must revert or leave c balance unchanged.
        // We express the rule as: if caller == c.owner() then recipientAfter == recipientBefore + cBalanceBefore
        // Use the public owner getter and observed balances.
        address owner = c.owner();
        if (caller == owner) {
            assert(recipientAfter == recipientBefore + cBalanceBefore);
        } else {
            assert(recipientAfter == recipientBefore || recipientAfter == recipientBefore + 0);
        }
    }
}

