    constructor(C _c) { c = _c; }
    function run(address caller, address recipient) public payable {
        require(caller != address(0) && recipient != address(0));
        // We must call withdrawAll from the provided caller address. Use a low-level call to simulate msg.sender.
        // Since we cannot change msg.sender in Solidity directly, we instead check behavior by attempting the call
        // via address(c).call with encoded selector, and observe whether it reverts.
        bool reverted;
        // encode calldata for withdrawAll(address)
        bytes memory data = abi.encodeWithSignature("withdrawAll(address)", recipient);
        (bool ok, ) = address(c).call{value: 0}(data);
        reverted = !ok;
        // The property: if caller is not the owner, the call should revert. We can observe owner via public getter.
        address owner = c.owner();
        // General rule: reverted == (caller != owner)
        assert(reverted == (caller != owner));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will pass in a recipient address that is a plain EOA (not a contract) by using this contract as a non-payable receiver to trigger transfer failure.
    // To make transfer fail in the original, we deploy no fallback payable here and send value to c so that transfer to this contract will revert.
    function run(address recipient, uint256 amount) public payable {
        require(true);
        // ensure this test contract has enough balance to fund c if needed
        if (amount > 0) {
            require(address(this).balance >= amount, "insufficient balance for funding");
            (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature(""));
            // funding c is a state-changing call on c, but it is not allowed because only calls that change c must be top-level and not nested in try — this is top-level
            // It's okay as a plain call to send Ether to c
            // ignore ok; even if funding fails, proceed — precondition didn't require funding
        }
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        // General rule: if caller is not owner then withdrawAll must revert. We cannot read owner, but this rule can be stated as: when caller is not the contract itself (i.e., msg.sender != owner) the call reverts.
        // However we cannot compare msg.sender to owner. Instead we assert that if the call did not revert then it must have been invoked by address(this) (owner) — i.e., only owner can succeed.
        assert(reverted || msg.sender == address(this));
    }
    receive() external payable { }
}

