contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // The test deployer will be the owner passed to C; ensure msg.sender is that owner when calling run.
    // We'll require that caller is the owner and that the recipient is a contract address with no payable fallback.
    // To model a non-payable recipient, we use this contract itself but with a fallback that reverts on plain transfers.

    // A receive that reverts to simulate a non-payable recipient when this test contract is used as recipient.
    receive() external payable { revert(); }

    function run(address payable recipient, uint256 deposit) public payable {
        // preconditions: caller must be the owner of C, and we must send some Ether to C so its balance is > 0
        require(msg.sender == c.owner());
        require(deposit > 0);
        require(address(this).balance >= deposit);

        // fund contract c so withdrawAll will attempt to transfer a nonzero balance
        (bool sent,) = address(c).call{value: deposit}("");
        require(sent);

        bool reverted; try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }

        // General rule: if recipient rejects plain transfers (modeled by this contract's receive reverting)
        // and the contract had a positive balance, then withdrawAll called by owner must revert.
        // We express "recipient rejects transfers" by checking that sending 1 wei to recipient via call reverts.
        bool recipientRejects;
        (bool ok,) = recipient.call{value: 1}("{}");
        recipientRejects = !ok;

        assert(!recipientRejects || reverted);
    }
}

