contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: actor (caller) and recipient address
    function testFuzz_property(address caller, address recipient) public {
        // keep addresses non-zero to be within wide admissible domain
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        // Fund the contract so transfer has something to send
        uint256 fund = 1 ether;
        vm.deal(address(c), fund);

        // Make the caller be the owner (only owner can withdraw)
        // The contract was constructed with owner = address(this); we need to simulate
        // a withdraw called by owner therefore set caller == address(this) OR prank as address(this).
        // Instead, we will call as the owner (address(this)) when caller equals address(this),
        // otherwise skip because non-owner calls revert and both versions behave same.
        vm.assume(caller == address(this));

        // Call withdrawAll as owner (address(this))
